import {CityMap} from './city.js';import {Player} from './player.js';import {Vehicle,VEHICLE_TYPES} from './vehicles.js';import {TrafficAI} from './traffic.js';import {PedestrianCrowd} from './pedestrians.js';import {WantedSystem} from './wanted.js';import {PoliceForce} from './police.js';import {Effects} from './effects.js';import {CombatSystem} from './combat.js';import {GangCrew} from './gang.js';import {DialogueBox} from './dialogue.js';import {MissionDirector} from './missions.js';import {SaveStore} from './save.js';import {SideActivities} from './activities.js';import {SoundSynth} from './audio.js';
export const World=class World{
 constructor(rng){this.rng=rng;this.callouts=[];this.calloutActive=null;this._nearMissCooldown=0;this._driftTime=0;this._collisionTimes=[];this._lastHeat=0;this._lastCalloutHeat=0;this._lastHeat=0;this.saveStore=new SaveStore();this.saveData=this.saveStore.load();this.savedPlayTimeMs=this.saveData?.playTimeMs||0;this.city=new CityMap(rng);this.time=0;this.playTimeMs=0;this.timeOfDay='golden';this.objective=null;this.playerStart={x:3830,y:2250};this.player=new Player(this.playerStart.x,this.playerStart.y);this.vehicles=[];for(let i=0;i<26;i++){const p=this.city.randomRoadPoint(rng);p.x+=rng.range(-18,18);this.vehicles.push(new Vehicle(p.x,p.y,rng.pick(Object.keys(VEHICLE_TYPES)),null,rng.chance(.5)?0:Math.PI));}for(let i=0;i<4;i++)this.vehicles.push(new Vehicle(535,680+i*145,rng.pick(Object.keys(VEHICLE_TYPES)),null,0));this.driving=null;this.heat=0;this.money=this.saveData?.money??500;this.health=100;this.bustMeter=0;this.busted=false;this.wasted=false;this.camera=null;this.traffic=new TrafficAI(this);this.pedestrians=new PedestrianCrowd(this);this.wanted=new WantedSystem(this);this.police=new PoliceForce(this);this.effects=new Effects(this);this.combat=new CombatSystem(this);this.gang=new GangCrew(this);this.dialogue=new DialogueBox();this.missions=new MissionDirector(this);this.activities=new SideActivities(this);this.audio=new SoundSynth(this);if(this.saveData){this.missions.index=Math.max(-1,Math.min(5,(this.saveData.missionIndex??0)-1));this.missions.state='available';for(const type of this.saveData.garageCars||[])if(VEHICLE_TYPES[type])this.vehicles.push(new Vehicle(4050,1700,type));this.completedAll=!!this.saveData.completedAll;this.missions.available();}}
 setTimeOfDay(value){if(!['day','dusk','night'].includes(value))return false;this.timeOfDay=value;return true;}
 saveWorld(){const d=this.saveData||{garageCars:[]};this.saveData={...d,money:this.money,missionIndex:Math.min(6,this.missions.index+1),completedAll:!!this.completedAll,garageCars:d.garageCars||[],playTimeMs:this.savedPlayTimeMs+Math.floor(this.playTimeMs*1000)};this.saveStore.save(this.saveData);}
 keepGarageCar(v){if(Math.hypot(v.x-4050,v.y-1700)<90){const d=this.saveData||{garageCars:[]};d.garageCars=[...(d.garageCars||[]),v.type];this.saveData=d;this.saveWorld();return true;}return false;}
 nearestCar(x,y,maxDist){let best=null,d=maxDist;for(const v of this.vehicles){if(v.driver)continue;const n=Math.hypot(x-v.x,y-v.y);if(n<d){best=v;d=n;}}return best;}
 pinCallout(mainText,subText='',options={}){this.pinnedCallout={mainText,subText,small:!!options.small,x:options.x??640,y:options.y??330};this.callouts=[];this.calloutActive=null;return this.pinnedCallout;} callout(mainText,subText='',small=false){this.callouts.push({mainText,subText,small,life:2.35,age:0});} step(dt,input={down:()=>false,actions:0}){this.time+=dt;this._nearMissCooldown=Math.max(0,this._nearMissCooldown-dt);if(this.calloutActive){this.calloutActive.life-=dt;if(this.calloutActive.life<=0)this.calloutActive=null;}if(!this.calloutActive&&this.callouts.length)this.calloutActive=this.callouts.shift();if(this.calloutActive)this.calloutActive.age+=dt;if(this.gameStarted)this.playTimeMs+=dt;this._gunfire=false;if(this.driving?._carjack){this.wanted.reportCrime('carjack');delete this.driving._carjack;}this.dialogue.update(dt,input);if(!this.dialogue.active){if(this.gameStarted)this.missions.update(dt,input);if(this.gameStarted&&!this.wasted&&!this.busted)this.player.update(dt,input,this);}this.traffic.update(dt);this.pedestrians.update(dt);this.combat.update(dt,input);this.gang.update(dt);this.wanted.update(dt);this.police.update(dt);if(this.heat>this._lastHeat&&this.heat>=2)this.callout('HEAT LEVEL '+this.heat+'!','PALMERA PD IN PURSUIT');if(this._lastHeat>=2&&this.heat===0){this.callout('ESCAPED!','+$150');this.money+=150;this._lastCalloutHeat=0;}this._lastHeat=this.heat;
 if(this.driving){const v=this.driving,kph=Math.abs(v.speed)*.14,near=this.vehicles.some(q=>q!==v&&q.driver==='traffic'&&Math.hypot(q.x-v.x,q.y-v.y)<26);if(near&&kph>90&&this._nearMissCooldown<=0){this.callout('NEAR MISS!','+$25');this.money+=25;this._nearMissCooldown=4;}if(v._handbrake&&kph>35){this._driftTime+=dt;if(this._driftTime>=1.1){this.callout('BIG DRIFT!','+$40');this.money+=40;this._driftTime=0;}}else this._driftTime=0;}
if(this.driving&&Math.abs(this.driving.speed)>45)for(const p of this.pedestrians.people)if(!p._hit&&Math.hypot(p.x-this.driving.x,p.y-this.driving.y)<18){p._hit=2;p.cower=2;this.wanted.reportCrime('pedestrian');}for(const p of this.pedestrians.people)if(p._hit>0)p._hit-=dt;for(let i=0;i<this.vehicles.length;i++)for(let j=i+1;j<this.vehicles.length;j++){const a=this.vehicles[i],b=this.vehicles[j];if(Math.hypot(a.x-b.x,a.y-b.y)<22&&a.speed>50&&b.speed>50){this._collisionTimes=this._collisionTimes.filter(t=>this.time-t<1);if(!this._collisionTimes.length){this._collisionTimes.push(this.time);if(a.driver!=='player'&&b.driver!=='player'){this.callout('TRAFFIC CHAOS!','+$60');this.money+=60;}}a.damage=Math.min(1,a.damage+.04);b.damage=Math.min(1,b.damage+.04);a.speed*=.4;b.speed*=.4;this.effects.impact((a.x+b.x)/2,(a.y+b.y)/2);if((a===this.driving||b===this.driving)&&Math.abs((a===this.driving?a:b).speed)>100)this.audio?.play('explosion');if(a===this.driving||b===this.driving){this.wanted.reportCrime('crash');if(a.type==='police'||b.type==='police')this.wanted.reportCrime('police');}for(const p of this.pedestrians.people)if(Math.hypot(p.x-a.x,p.y-a.y)<50)p.cower=2;}}this.effects.update(dt);this.activities.update(dt,this);this.audio.update(dt,this);}
